import { DACN } from "@/services/DACN/typings";
import { getListReports, reviewReport } from "@/services/DACN/report";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { MyDatePicker } from "@/components/MyDatePicker";
import { toDateOnlyUTC } from "@/lib/utils";
import { Center, Loader } from "@mantine/core";
import { set } from "react-hook-form";
import { notifications } from "@mantine/notifications";

type ReportStatus = "SUBMITTED" | "REVIEWED" | "DRAFT";

type WeeklyReport = {
  id: string;
  employeeId: string;
  employeeName: string;
  department: string;
  weekStart: string; // YYYY-MM-DD
  weekEnd: string; // YYYY-MM-DD
  createdAt: string; // ISO
  updatedAt: string; // ISO
  progress: number; // 0..100
  accomplishments: string;
  inProgress: string;
  planNextWeek: string;
  blockers: string;
  links: string;
  hours: number;
  status: ReportStatus;
  managerComment: string;
};

const STORAGE_KEY = "weekly_reports";

function safeId() {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (crypto as any).randomUUID() as string;
  }
  return `wr_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function clampProgress(n: number) {
  if (Number.isNaN(n)) return 0;
  return Math.max(0, Math.min(100, Math.round(n)));
}

function formatDateShort(ymdOrIso: string) {
  const d = new Date(ymdOrIso);
  if (Number.isNaN(d.getTime())) return ymdOrIso;
  return d.toLocaleDateString("vi-VN", {
    year: "numeric",
    month: "short",
    day: "2-digit",
  });
}

function statusLabel(s: ReportStatus) {
  switch (s) {
    case "SUBMITTED":
      return "???? n???p";
    case "REVIEWED":
      return "???? duy???t";
    case "DRAFT":
      return "B???n nh??p";
    default:
      return s;
  }
}

function statusVariant(
  s: ReportStatus,
): "default" | "secondary" | "destructive" {
  switch (s) {
    case "REVIEWED":
      return "default";
    case "DRAFT":
      return "secondary";
    case "SUBMITTED":
    default:
      return "default";
  }
}

type Filters = {
  q: string;
  status: "all" | ReportStatus;
  submittedAt: string;
};

function ProgressBar({ value }: { value: number }) {
  const v = clampProgress(value);
  return (
    <div className="h-2 w-full rounded-full bg-muted">
      <div
        className="h-2 rounded-full bg-emerald-500"
        style={{ width: `${v}%` }}
      />
    </div>
  );
}

function EmptyState({ title, hint }: { title: string; hint?: string }) {
  return (
    <div className="rounded-xl border bg-white p-10 text-center">
      <div className="mx-auto mb-3 grid h-10 w-10 place-items-center rounded-full bg-muted">
        <MessageSquareText className="h-5 w-5 text-muted-foreground" />
      </div>
      <div className="text-sm font-semibold text-foreground">{title}</div>
      {hint ? (
        <div className="mt-1 text-xs text-muted-foreground">{hint}</div>
      ) : null}
    </div>
  );
}

export default function WeeklyReportsPage() {
  const [reports, setReports] = React.useState<DACN.ManagerReportResponseDto[]>(
    [],
  );
  const [selectedId, setSelectedId] = React.useState<string | null>(null);
  const [review, setReview] = React.useState<string>("");
  const [error, setError] = React.useState<string | null>(null);
  const [updated, setUpdated] = React.useState<boolean>(false);
  const [currentPage, setCurrentPage] = React.useState<number>(0);
  const [totalPage, setTotalPage] = React.useState<number>(0);
  const [filters, setFilters] = React.useState<Filters>({
    q: "",
    status: "all",
    submittedAt: "",
  });

  const [createOpen, setCreateOpen] = React.useState(false);
  const [draft, setDraft] = React.useState<
    Omit<WeeklyReport, "id" | "createdAt" | "updatedAt">
  >({
    employeeId: "",
    employeeName: "",
    department: "Engineering",
    weekStart: "",
    weekEnd: "",
    progress: 0,
    accomplishments: "",
    inProgress: "",
    planNextWeek: "",
    blockers: "",
    links: "",
    hours: 40,
    status: "SUBMITTED",
    managerComment: "",
  });

  React.useEffect(() => {
    const fetchReport = async () => {
      try {
        const res = await getListReports({
          page: 1,
          limit: 10,
        });
        setReports(
          res.data?.data.filter(
            (r: DACN.ManagerReportResponseDto) => r.status !== "DRAFT",
          ) ?? [],
        );
      } catch (error) {
        console.error("Failed to fetch report:", error);
      }
    };
    fetchReport();
  }, [createOpen, updated]);

  const filtered = React.useMemo(() => {
    const q = filters.q.trim().toLowerCase();
    const filterReports = reports
      .filter((r) => {
        if (
          q.length > 0 &&
          q.includes(r.employee?.firstName.toLowerCase()) === false &&
          q.includes(r.employee?.middleName.toLowerCase()) === false &&
          q.includes(r.employee?.lastName.toLowerCase()) === false
        )
          return false;
        if (filters.status !== "all" && r.status !== filters.status)
          return false;

        if (
          filters.submittedAt &&
          toDateOnlyUTC(r.created_at) !== toDateOnlyUTC(filters.submittedAt)
        ) {
          return false;
        }

        return true;
      })
      .sort((a, b) => (a.created_at < b.created_at ? 1 : -1));
    setTotalPage(Math.ceil(filterReports.length / 4));
    return filterReports.slice(currentPage * 4, currentPage * 4 + 4);
  }, [reports, filters, currentPage]);

  const selected = React.useMemo(
    () => reports.find((r) => r.id === selectedId) ?? null,
    [reports, selectedId],
  );

  const counts = React.useMemo(() => {
    return {
      total: reports.length,
      submitted: reports.filter((r) => r.status === "SUBMITTED").length,
      reviewed: reports.filter((r) => r.status === "REVIEWED").length,
      needsChanges: reports.filter((r) => r.status === "DRAFT").length,
    };
  }, [reports]);

  const handleReview = async () => {
    if (!selectedId) return;
    if (review.trim().length === 0) {
      setError("Vui l??ng nh???p feedback tr?????c khi duy???t b??o c??o.");
      return;
    }
    try {
      await reviewReport(selectedId, { review });
      notifications.show({
        title: "Th??nh c??ng",
        message: "B??o c??o ???? ???????c duy???t th??nh c??ng.",
        color: "green",
      });
      setError(null);
      setUpdated(!updated);
    } catch (error) {
      notifications.show({
        title: "L???i",
        message: "???? c?? l???i x???y ra khi duy???t b??o c??o. Vui l??ng th??? l???i.",
        color: "red",
      });
    }
  };

  const submitDraft = () => {
    if (!draft.employeeId.trim() || !draft.employeeName.trim()) return;
    if (!draft.weekStart || !draft.weekEnd) return;

    const nowIso = new Date().toISOString();
    const item: DACN.ManagerReportResponseDto = {
      ...draft,
      id: safeId(),
      week_starting: draft.weekStart,
      created_at: nowIso,
      updated_at: nowIso,
      accomplishment: draft.accomplishments,
      employee: draft.employeeName,
      in_progress: draft.inProgress,
      plan: draft.planNextWeek,
      progress_percentage: clampProgress(draft.progress),
      status: "SUBMITTED",
    };
    setReports((prev) => [item, ...prev]);
    setSelectedId(item.id);
    setCreateOpen(false);
    setDraft((p) => ({
      ...p,
      employeeId: "",
      employeeName: "",
      weekStart: "",
      weekEnd: "",
      accomplishments: "",
      inProgress: "",
      planNextWeek: "",
      blockers: "",
      links: "",
      progress: 0,
      hours: 40,
    }));
  };

  return (
    <div className="mx-auto w-full max-w-[1400px] px-6 py-6">
