                {HOURS_OF_DAY.map((hour) => (
                  <div key={hour} className="h-[80px] border-b border-gray-100 w-full shrink-0"></div>
                ))}
              </div>

              {displayDays.map((day, colIndex) => {
                const isTodayLocal = isSameDay(day, today);
                const dayStart = new Date(day);
                dayStart.setHours(0, 0, 0, 0);
                const dayEnd = new Date(dayStart);
                dayEnd.setDate(dayEnd.getDate() + 1);

                const dayEvents = mappedEvents.filter((e) => overlapsDay(e, day));

                return (
                  <div
                    key={colIndex}
                    className={`relative border-r border-gray-100 last:border-r-0 ${
                      isTodayLocal ? "bg-[#F0FFF7]/30" : ""
                    }`}
                  >
                    {dayEvents.map((event) => {
                      let top = 0;
                      let height = 24;

                      if (event.type === "LEAVE_REQUEST") {
                        // ????n ngh??? ph??p d??i ng??y: t??nh b???ng thu???t to??n ng???t ng??y (clamp)
                        const segmentStart = event.start.getTime() > dayStart.getTime() ? event.start : dayStart;
                        const segmentEnd = event.end.getTime() < dayEnd.getTime() ? event.end : dayEnd;
                        const startDiffMinutes = (segmentStart.getTime() - dayStart.getTime()) / 60000;
                        const endDiffMinutes = (segmentEnd.getTime() - dayStart.getTime()) / 60000;
                        top = startDiffMinutes * (80 / 60);
                        height = Math.max((endDiffMinutes - startDiffMinutes) * (80 / 60), 24);
                      } else {
                        // BOOKING (L???ch h???p ?????nh k???): Ch??? quan t??m ????ng s??? gi???/ph??t, b??? qua s??? sai l???ch ng??y
                        const startMins = event.start.getHours() * 60 + event.start.getMinutes();
                        let endMins = event.end.getHours() * 60 + event.end.getMinutes();
                        
                        // ????? ph??ng tr?????ng h???p l???ch v???t ngang qua ng??y m???i (vd: 23:00 t???i 01:00) 
                        if (endMins <= startMins) {
                          if (event.end.getTime() > event.start.getTime()) {
                            endMins = 24 * 60; 
                          } else {
                            endMins = startMins + 60; // Fallback an to??n 1 ti???ng
                          }
                        }
                        
                        top = startMins * (80 / 60);
                        height = Math.max((endMins - startMins) * (80 / 60), 24);
                      }

                      return (
                        <div
                          key={`${event.id}:${colIndex}`}
                          className={`absolute left-1.5 right-1.5 rounded-md border-l-[3px] p-2 overflow-hidden transition-all hover:z-10 hover:shadow-md cursor-pointer ${event.color.bg} ${event.color.border}`}
                          style={{ top: `${top}px`, height: `${height}px` }}
                        >
                          <div className={`text-[11px] font-bold truncate leading-tight ${event.color.text}`}>
                            {event.title}
                          </div>
                          {height >= 40 ? (
                            <div className={`text-[10px] opacity-80 truncate mt-1 ${event.color.text}`}>
                              {formatTime(event.start)} - {formatTime(event.end)}
                              {event.subtitle ? ` ??? ${event.subtitle}` : ""}
                            </div>
                          ) : null}
                        </div>
                      );
                    })}
                  </div>
                );
              })}

              {isCurrentView ? (
                <div
                  className="absolute w-full flex items-center pointer-events-none z-20"
                  style={{ top: `${redLineTop}px` }}
                >
                  <div className="w-2.5 h-2.5 rounded-full bg-red-500 absolute -left-1.5 shadow-sm"></div>
                  <div className="w-full h-[2px] bg-red-500 shadow-sm"></div>
                </div>
              ) : null}
            </div>
          </div>
        </div>
      </main>

      <style jsx global>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 8px;
          height: 8px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #F8FAFC;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background-color: #CBD5E1;
          border-radius: 20px;
          border: 2px solid #F8FAFC;
        }
        .custom-scrollbar:hover::-webkit-scrollbar-thumb {
          background-color: #94A3B8;
        }
      `}</style>
    </div>
  );
}

"use client";

import { 
  Banknote, 
  TrendingUp, 
  Calendar, 
  Wallet, 
  Eye
} from "lucide-react";
import { useMemo, useState } from "react";
import { useRequest } from "ahooks";

import { getMyPayrollByMonth } from "@/services/DACN/Payroll";

// --- Helper: Format ti???n t??? (???? chuy???n sang VND) ---
const formatCurrency = (amount: number) => {
  return new Intl.NumberFormat('vi-VN', {
    style: 'currency',
    currency: 'VND',
    minimumFractionDigits: 0,
  }).format(amount);
};

type SalaryHistoryItem = {
  year: number;
  month: number;
  total: number;
  deduction: number;
  taxAmount: number;
  net: number;
  status: string;
};

function toNumber(value: unknown): number {
  const n = typeof value === "number" ? value : Number(String(value ?? ""));
  return Number.isFinite(n) ? n : 0;
}

function nextPayLabel(year: number, month: number) {
  if (!Number.isFinite(year) || !Number.isFinite(month) || month < 1 || month > 12) return "-";
  const lastDay = new Date(year, month, 0);
  return new Intl.DateTimeFormat("vi-VN", { day: "2-digit", month: "short" }).format(lastDay);
}

export default function PayrollPage() {
  const now = new Date();
  const realCurrentYear = now.getFullYear();
  const realCurrentMonth = now.getMonth() + 1;

  const [year, setYear] = useState(realCurrentYear);
  const [month, setMonth] = useState(realCurrentMonth);

  // 1. G???I API CHO PHI???U L????NG CHI TI???T (B??n tr??i)
  const { data, loading, error, refresh } = useRequest(
    () => getMyPayrollByMonth({ year, month }),
    { refreshDeps: [year, month] },
  );

  const p = (data as any)?.data ?? data;

  const totalEarnings = toNumber(p?.grossSalary);
  const totalDeductions = toNumber(p?.insuranceAmount) + toNumber(p?.taxAmount) + toNumber(p?.deduction);
  const netSalary = toNumber(p?.netSalary);

  const currentPayslip = useMemo(() => {
    const y = Number(p?.year ?? year);
    const m = Number(p?.month ?? month);
    const mm = String(m).padStart(2, "0");
    const employeeId = p?.employeeId ? String(p.employeeId) : "";
    const paymentDate = p?.paidAt ?? p?.finalizedAt ?? p?.updatedAt ?? "";

    return {
      month: `${mm}/${y}`,
      employeeId: employeeId ? `ID:${employeeId}` : "-",
      department: p?.employee?.department?.name ? String(p.employee.department.name) : "-",
      paymentDate: paymentDate ? new Intl.DateTimeFormat("vi-VN").format(new Date(paymentDate)) : "-",
      earnings: [
        { label: "L????ng c?? b???n", amount: toNumber(p?.basicSalarySnapshot) },
        { label: "Tr??? c???p", amount: toNumber(p?.allowance) },
      ],
      deductions: [
        { label: "B???o hi???m", amount: toNumber(p?.insuranceAmount) },
        { label: "Thu??? thu nh???p", amount: toNumber(p?.taxAmount) },
        { label: "C??c kho???n kh???u tr??? kh??c", amount: toNumber(p?.deduction) },
