                        }`}>
                          {h.status}
                        </span>
                        <button
                          type="button"
                          onClick={() => {
                            setYear(h.year);
                            setMonth(h.month);
                          }}
                          className={`p-1.5 rounded-md transition-colors ${
                            isSelected ? 'bg-[#0B9F57] text-white' : 'text-[#B8BDC5] hover:text-[#0B9F57] hover:bg-gray-100'
                          }`}
                          title="Xem chi ti???t"
                        >
