"use client";

import * as React from "react";
import {
  Calendar,
  Filter,
  RefreshCcw,
  MessageSquareText,
  Plus,
  Search,
  Send,
  ChevronLeft,
  ChevronRight,
} from "lucide-react";
import { ReadonlyTextarea } from "@/components/ReadonlyTextarea";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { notifications } from "@mantine/notifications";
import { DACN } from "@/services/DACN/typings";
import {
  createReport,
  getMyReport,
  updateReport,
  submitReport,
} from "@/services/DACN/report";
import { Textarea } from "@/components/ui/textarea";
import { toDateOnlyUTC, formatDate } from "@/lib/utils";
import { Controller, set, useForm } from "react-hook-form";
import { z } from "zod";
import { zodResolver } from "@hookform/resolvers/zod";

import { Center, Loader } from "@mantine/core";

const reportSchema = z.object({
  week_starting: z
    .string()
    .regex(/^\d{4}-\d{2}-\d{2}$/, "Vui l??ng ch???n ng??y b???t ?????u tu???n"),
  progress_percentage: z.number().min(1, "Ti???n ????? l?? b???t bu???c").max(100),
  accomplishment: z
    .string()
    .min(10, "C??ng vi???c ???? ho??n th??nh l?? b???t bu???c")
    .max(500),
  in_progress: z
    .string()
    .min(10, "C??ng vi???c ??ang th???c hi???n l?? b???t bu???c")
    .max(500),
  plan: z.string().min(10, "K??? ho???ch l?? b???t bu???c").max(500),
  blocker: z.string().max(500),
  progress_notes: z.string().max(500),
});

type ReportFormData = z.infer<typeof reportSchema>;
type ReportStatus = "SUBMITTED" | "REVIEWED" | "DRAFT";

type WeeklyReport = {
  id: string;
  employeeId: string;
  employeeName: string;
  department: string;
  weekStart: string; // YYYY-MM-DD
  weekEnd: string; // YYYY-MM-DD
  createdAt: string; // ISO
  updatedAt: string; // ISO
  progress: number; // 0..100
  accomplishments: string;
  inProgress: string;
  planNextWeek: string;
  blockers: string;
  links: string;
  hours: number;
  status: ReportStatus;
  managerComment: string;
};

const STORAGE_KEY = "weekly_reports";

function safeId() {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (crypto as any).randomUUID() as string;
  }
  return `wr_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function clampProgress(n: number) {
  if (Number.isNaN(n)) return 0;
  return Math.max(0, Math.min(100, Math.round(n)));
}

function formatDateShort(ymdOrIso: string) {
  const d = new Date(ymdOrIso);
  if (Number.isNaN(d.getTime())) return ymdOrIso;
  return d.toLocaleDateString("vi-VN", {
    year: "numeric",
    month: "short",
    day: "2-digit",
  });
}

function statusLabel(s: ReportStatus) {
  switch (s) {
    case "SUBMITTED":
      return "???? n???p";
    case "REVIEWED":
      return "???? duy???t";
    case "DRAFT":
      return "B???n nh??p";
    default:
      return s;
  }
}

function statusVariant(
  s: ReportStatus,
): "default" | "secondary" | "destructive" {
  switch (s) {
    case "REVIEWED":
      return "default";
    case "DRAFT":
      return "secondary";
    case "SUBMITTED":
    default:
      return "default";
  }
}

type Filters = {
  q: string;
  status: "all" | ReportStatus;
  submittedAt: string;
};

function ProgressBar({ value }: { value: number }) {
  const v = clampProgress(value);
  return (
    <div className="h-2 w-full rounded-full bg-muted">
      <div
        className="h-2 rounded-full bg-emerald-500"
        style={{ width: `${v}%` }}
      />
    </div>
  );
}

function EmptyState({ title, hint }: { title: string; hint?: string }) {
  return (
    <div className="rounded-xl border bg-white p-10 text-center">
      <div className="mx-auto mb-3 grid h-10 w-10 place-items-center rounded-full bg-muted">
        <MessageSquareText className="h-5 w-5 text-muted-foreground" />
      </div>
      <div className="text-sm font-semibold text-foreground">{title}</div>
      {hint ? (
        <div className="mt-1 text-xs text-muted-foreground">{hint}</div>
      ) : null}
    </div>
  );
}

export default function WeeklyReportsPage() {
  const [reports, setReports] = React.useState<DACN.ReportResponseDto[]>([]);
  const [selectedReport, setSelectedReport] =
    React.useState<DACN.ReportResponseDto | null>(null);
  const [loading, setLoading] = React.useState(false);
  const [updated, setUpdated] = React.useState(false);
  const [isEditing, setIsEditing] = React.useState(false);
  const [currentPage, setCurrentPage] = React.useState<number>(0);
  const [totalPage, setTotalPage] = React.useState<number>(0);
  const [filters, setFilters] = React.useState<Filters>({
    q: "",
    status: "all",
    submittedAt: "",
  });
  const {
    register,
    control,
    handleSubmit,
    watch,
    formState: { errors },
    reset,
  } = useForm<ReportFormData>({
    resolver: zodResolver(reportSchema),
  });
  const [createOpen, setCreateOpen] = React.useState(false);

  React.useEffect(() => {
    const fetchReport = async () => {
      try {
        const res = await getMyReport({
          page: 1,
          limit: 10,
        });
        //console.log("Fetched my report:", res.data?.data);
        if (selectedReport) {
          setSelectedReport(
            res.data?.data.find(
              (r: DACN.ReportResponseDto) => r.id === selectedReport.id,
            ) ?? null,
          );
        }
        setReports(res.data?.data);
      } catch (error) {
        console.error("Failed to fetch report:", error);
      } finally {
        setLoading(false);
      }
    };
    setLoading(true);
    fetchReport();
  }, [createOpen, updated]);

  // React.useEffect(() => {
  //   const initial = readReports();
  //   setReports(initial);
  //   setSelectedId(initial[0]?.id ?? null);
  // }, []);
  // React.useEffect(() => {
  //   if (reports.length === 0) return;
  //   writeReports(reports);
  // }, [reports]);

  // const departments = React.useMemo(() => {
  //   const set = new Set<string>();
  //   for (const r of reports) set.add(r.department);
  //   return Array.from(set).sort();
  // }, [reports]);

  const filtered = React.useMemo(() => {
    const q = filters.q.trim().toLowerCase();

    const filteredReports = reports
      .filter((r) => {
        if (filters.status !== "all" && r.status !== filters.status)
          return false;

        if (
          filters.submittedAt &&
          toDateOnlyUTC(r.created_at) !== toDateOnlyUTC(filters.submittedAt)
        ) {
          return false;
        }

        return true;
      })
      .sort((a, b) => (a.created_at < b.created_at ? 1 : -1));
    if (!selectedReport) {
      setSelectedReport(filteredReports[0] ?? null);
    }

    setTotalPage(Math.ceil(filteredReports.length / 4));
    return filteredReports.slice(currentPage * 4, currentPage * 4 + 4);
  }, [reports, filters, currentPage]);
  const counts = React.useMemo(() => {
    return {
      total: reports.length,
      submitted: reports.filter((r) => r.status === "SUBMITTED").length,
      reviewed: reports.filter((r) => r.status === "REVIEWED").length,
      draft: reports.filter((r) => r.status === "DRAFT").length,
    };
  }, [reports]);

  const updateSelected = async () => {
    if (!selectedReport) return;
    if (
      selectedReport.accomplishment.trim() === "" ||
      selectedReport.in_progress.trim() === "" ||
      selectedReport.plan.trim() === ""
    )
      return;
    const updateBody: DACN.UpdateReportDto = {
      accomplishment: selectedReport.accomplishment,
      in_progress: selectedReport.in_progress,
      plan: selectedReport.plan,
      blocker: selectedReport.blocker,
      progress_percentage: Number(selectedReport.progress_percentage),
      progress_notes: selectedReport.progress_notes,
    };
    try {
      await updateReport(updateBody, selectedReport.id);
      notifications.show({
        title: "Th??nh c??ng",
        message: "C???p nh???t b??o c??o th??nh c??ng.",
        color: "green",
      });
      setUpdated(!updated);
      setIsEditing(false);
    } catch (error) {
      notifications.show({
        title: "???? c?? l???i x???y ra",
        message:
          "???? c?? l???i x???y ra khi c???p nh???t b??o c??o. Vui l??ng c???p nh???t l???i sau.",
        color: "red",
      });
    }
  };

  const handleSubmitReport = async () => {
    if (!selectedReport) return;
    try {
      await submitReport(selectedReport.id);
      notifications.show({
        title: "Th??nh c??ng",
        message: "B??o c??o ???? ???????c n???p th??nh c??ng.",
        color: "green",
      });
      setUpdated(!updated);
    } catch (error) {
      notifications.show({
        title: "???? c?? l???i x???y ra",
        message: "???? c?? l???i x???y ra khi n???p b??o c??o. Vui l??ng thao t??c l???i.",
        color: "red",
      });
    }
  };

  const onSubmit = async (data: ReportFormData) => {
    const newReport: DACN.CreateReportRequestDto = {
      week_starting: data.week_starting,
      accomplishment: data.accomplishment,
      in_progress: data.in_progress,
      plan: data.plan,
      blocker: data.blocker,
      progress_percentage: data.progress_percentage,
      progress_notes: data.progress_notes,
    };
    try {
      await createReport(newReport);
      notifications.show({
        title: "???? n???p b??o c??o",
        message: "B??o c??o h??ng tu???n c???a b???n ???? ???????c n???p th??nh c??ng.",
        color: "green",
      });
      reset();
      setCreateOpen(false);
    } catch (error) {
      notifications.show({
        title: "N???p b??o c??o th???t b???i",
        message:
          "???? c?? l???i x???y ra trong qu?? tr??nh n???p b??o c??o. Vui l??ng th??? l???i.",
        color: "red",
      });
    }
  };

  return (
    <div className="mx-auto w-full max-w-[1400px] px-6 py-6">
      <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <div className="text-xl font-semibold text-foreground">
            B??o c??o h??ng tu???n
          </div>
          <div className="mt-1 text-xs text-muted-foreground">
            T???ng:{" "}
            <span className="font-semibold text-foreground">
              {counts.total}
            </span>{" "}
            ?? ???? n???p{" "}
            <span className="font-semibold text-foreground">
              {counts.submitted}
            </span>{" "}
            ?? ???? duy???t{" "}
            <span className="font-semibold text-foreground">
              {counts.reviewed}
            </span>{" "}
            ?? B???n nh??p{" "}
            <span className="font-semibold text-foreground">
              {counts.draft}
            </span>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <Dialog open={createOpen} onOpenChange={setCreateOpen}>
            <DialogTrigger asChild>
              <Button className="rounded-full" type="button">
                <Plus className="mr-2 h-4 w-4" />
                B??o c??o m???i
              </Button>
            </DialogTrigger>
            <DialogContent className="w-full max-w-3xl max-h-[90vh] overflow-y-auto">
              <DialogHeader className="mb-4">
                <DialogTitle>N???P B??O C??O H??NG TU???N</DialogTitle>
              </DialogHeader>
              <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
                <div className="grid grid-cols-1 gap-4 md:grid-cols-2 md:gap-2">
                  <div>
                    <Label>
                      Ng??y b???t ?????u tu???n <span className="text-red-500">*</span>
                    </Label>
                    <Controller
                      control={control}
                      name="week_starting"
                      render={({ field }) => (
                        <div className="relative group mt-1">
                          <Calendar className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground group-hover:text-[#4F7D7B] transition-colors" />
                          <Input
                            type="date"
                            value={
                              typeof field.value === "string" ? field.value : ""
                            }
                            onChange={(e) => field.onChange(e.target.value)}
                            onBlur={field.onBlur}
                            name={field.name}
                            ref={field.ref}
                            onClick={(e) => e.currentTarget.showPicker?.()}
                            className="bg-white pl-9 cursor-pointer hover:border-[#4F7D7B] transition-colors [&::-webkit-calendar-picker-indicator]:hidden"
                            required
                          />
                        </div>
                      )}
                    />
                    {errors.week_starting && (
                      <p className="mt-1 text-sm text-red-500">
                        {errors.week_starting.message}
                      </p>
                    )}
                  </div>

                  <div>
                    <Label>
                      Ti???n ????? (%) <span className="text-red-500">*</span>
                    </Label>
                    <Input
                      type="number"
                      {...register("progress_percentage", {
                        valueAsNumber: true,
                      })}
                      min={0}
                      max={100}
                      className="mt-1 bg-white"
                    />
                    {errors.progress_percentage && (
                      <p className="mt-1 text-sm text-red-500">
                        {errors.progress_percentage.message}
                      </p>
                    )}
                  </div>

                  <div>
                    <Label>
                      C??ng vi???c ???? ho??n th??nh{" "}
                      <span className="text-red-500">*</span>
                    </Label>
                    <Textarea
                      className="mt-1"
                      {...register("accomplishment")}
                      rows={5}
                      placeholder="Vi???c ???? ho??n th??nh..."
                    />
                    {errors.accomplishment && (
                      <p className="mt-1 text-sm text-red-500">
                        {errors.accomplishment.message}
                      </p>
                    )}
                  </div>
                  <div>
                    <Label>
                      C??ng vi???c ??ang th???c hi???n{" "}
                      <span className="text-red-500">*</span>
                    </Label>
                    <Textarea
                      {...register("in_progress")}
                      className="mt-1"
                      rows={5}
